import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1787777737000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>The complete set. <strong>Every variable is optional</strong> — the server works out of the box against the free public OpenStreetMap services. There is no config file and no command-line flag.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>OSM_USER_AGENT</code></td><td>no</td><td><code>osm-mcp/&lt;version&gt; (+https://github.com/ni-c/osm-mcp)</code></td><td>User-Agent sent to every service. Nominatim requires a real, identifying one.</td></tr><tr><td><code>NOMINATIM_BASE_URL</code></td><td>no</td><td><code>https://nominatim.openstreetmap.org</code></td><td>Geocoding / reverse geocoding</td></tr><tr><td><code>PHOTON_BASE_URL</code></td><td>no</td><td><code>https://photon.komoot.io</code></td><td>Typo-tolerant geocoding</td></tr><tr><td><code>OSRM_BASE_URL</code></td><td>no</td><td><code>https://routing.openstreetmap.de</code></td><td>Routing, matrices, trip optimization. Must serve the <code>routed-{car,bike,foot}</code> path prefixes (FOSSGIS layout).</td></tr><tr><td><code>OVERPASS_BASE_URL</code></td><td>no</td><td><code>https://overpass-api.de/api/interpreter,https://overpass.private.coffee/api/interpreter</code></td><td>Comma-separated Overpass interpreter endpoints, tried in order on 429/5xx</td></tr><tr><td><code>VALHALLA_BASE_URL</code></td><td>no</td><td><code>https://valhalla1.openstreetmap.de</code></td><td>Isochrones</td></tr><tr><td><code>ORS_API_KEY</code></td><td>no</td><td>—</td><td>Optional <a href="https://openrouteservice.org" target="_blank" rel="noreferrer">OpenRouteService</a> key (secret). When set, routes, matrices and isochrones use ORS instead of OSRM/Valhalla. Free tier: 2 000 directions/day, 40/minute.</td></tr><tr><td><code>ORS_BASE_URL</code></td><td>no</td><td><code>https://api.openrouteservice.org</code></td><td>OpenRouteService endpoint</td></tr><tr><td><code>OSM_CACHE_TTL</code></td><td>no</td><td><code>3600</code></td><td>Seconds identical upstream responses are served from the in-memory cache (<code>0</code> disables caching)</td></tr></tbody></table><h2 id="validation-rules" tabindex="-1">Validation rules <a class="header-anchor" href="#validation-rules" aria-label="Permalink to “Validation rules”">​</a></h2><p>Every <code>*_BASE_URL</code> value is validated at startup; the server exits with a <code>ConfigError</code> when a rule is violated. Deliberately, the offending <strong>value is never echoed</strong> in the error message — an API key pasted into the wrong variable would otherwise be printed verbatim into the MCP host&#39;s log.</p><table tabindex="0"><thead><tr><th>Rule</th><th>Behaviour</th></tr></thead><tbody><tr><td>Unparseable by <code>new URL()</code></td><td>Server exits with an error</td></tr><tr><td>Scheme other than <code>http</code>/<code>https</code></td><td>Server exits with an error</td></tr><tr><td>Contains <code>user:pass@</code></td><td>Server exits with an error</td></tr><tr><td>Contains a query string or fragment</td><td>Server exits with an error</td></tr><tr><td>Trailing slashes</td><td>Stripped</td></tr><tr><td>Plain <code>http</code> to a remote host</td><td>Warning on stderr, server continues</td></tr><tr><td>Plain <code>http</code> to loopback</td><td>No warning</td></tr></tbody></table><p>Loopback means <code>localhost</code>, <code>*.localhost</code>, <code>127.*</code> or <code>::1</code> (IPv6 brackets are stripped before matching).</p><p>Two more rules:</p><ul><li><code>OSM_CACHE_TTL</code> must be a plain number of seconds; anything else exits.</li><li><code>ORS_BASE_URL</code> must be <code>https://</code> (or loopback) while <code>ORS_API_KEY</code> is set — the key travels in an <code>Authorization</code> header and would otherwise cross the network unencrypted.</li></ul><h2 id="ors-api-key-handling" tabindex="-1"><code>ORS_API_KEY</code> handling <a class="header-anchor" href="#ors-api-key-handling" aria-label="Permalink to “ORS_API_KEY handling”">​</a></h2><p>The only secret. It is <strong>deleted from <code>process.env</code> immediately after loading</strong> — before any validation can throw — so it is not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code> even if a caller catches the <code>ConfigError</code> and keeps running. It is also redacted from error messages before they reach the model context.</p><h2 id="not-configurable" tabindex="-1">Not configurable <a class="header-anchor" href="#not-configurable" aria-label="Permalink to “Not configurable”">​</a></h2><table tabindex="0"><thead><tr><th>Behaviour</th><th>Value</th></tr></thead><tbody><tr><td>Rate limit, per service</td><td>~1 request/second (ORS: ~40/minute)</td></tr><tr><td>Overpass concurrency</td><td>2 requests</td></tr><tr><td>Request timeout</td><td>30 s (Overpass: 40 s)</td></tr><tr><td>HTTP redirects</td><td>never followed</td></tr><tr><td>Cache size</td><td>500 entries, ≤ 1 MB each</td></tr><tr><td>Matrix size</td><td>origins + destinations ≤ 25</td></tr><tr><td>Turn-by-turn steps</td><td>first 100</td></tr><tr><td><code>poi_details</code> tag budget</td><td>60 tags, 500 chars per value</td></tr></tbody></table><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>OSM_ALLOW_TOOLS</code></td><td>no</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>OSM_DENY_TOOLS</code></td><td>no</td><td>Same syntax; subtracted from whatever the allow list left</td></tr></tbody></table><p>Both are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>. Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>OSM_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list, and selects <code>geocode</code>, <code>reverse_geocode</code>, <code>find_nearby_pois</code>, <code>poi_details</code>, <code>route</code>, <code>map_link</code>.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_x</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};